CREATE TABLE FATTI (
  CodTempo INTEGER  NOT NULL,
  CodTar INTEGER  NOT NULL,
  CodLuogo_Chiamante INTEGER  NOT NULL,
  CodLuogo_Chiamato INTEGER  NOT NULL,
  Prezzo INTEGER  NOT NULL,
  NumChiamate INTEGER  NOT NULL,
  PRIMARY KEY (CodTempo, CodTar, CodLuogo_Chiamante, CodLuogo_Chiamato),
  FOREIGN KEY (CodTempo) REFERENCES TEMPO(CodTempo),
  FOREIGN KEY (CodTar) REFERENCES TARIFFA(CodTar),
  FOREIGN KEY (CodLuogo_Chiamante) REFERENCES LUOGO(CodLuogo),
  FOREIGN KEY (CodLuogo_Chiamato) REFERENCES LUOGO(CodLuogo)
);
